from scipy.optimize import least_squares
rng=np.random.default_rng(0)
def nm(model,p0s):
    best=None
    for p0 in p0s:
        try:
            r=least_squares(lambda p: model(p)-sigma, p0, max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception as e: pass
    return np.mean((sigma-model(best.x))**2)/np.var(sigma), np.round(best.x,4)
